window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-12c9ae3be71f6ecb"]={"versions": [{"id": "FIG-12c9ae3be71f6ecb", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der AUTOSAR-E2E-Bibliothek (Profile 5). Das Diagramm modelliert den internen Kontrollfluss des Teilschritts „Verify inputs of the protect function“ innerhalb der Funktion <code>E2E_P05Protect()</code>, welche den Eingabeparameter-Check vor der eigentlichen Berechnung von Counter und CRC kapselt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontextfunktion: <code>E2E_P05Protect()</code></li>\n<li>Eingangsparameter / Entitäten:</li>\n<li><code>Config</code>: Zeiger auf die E2E-Profile-5-Konfigurationsstruktur (<code>E2E_P05ConfigType</code>), enthält u. a. das Feld <code>DataLength</code> (Länge in Bits)</li>\n<li><code>State</code>: Zeiger auf den Zustandsvektor (<code>E2E_P05ProtectStateType</code>)</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array (<code>uint8*</code>)</li>\n<li><code>Length</code>: Datenlänge in Bytes (<code>uint16</code>)</li>\n<li>Entscheidungsknoten (Decision Nodes):</li>\n<li>Nullzeiger-Prüfung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code></li>\n<li>Längenprüfung: <code>Length == Config-&gt;DataLength/8</code></li>\n<li>Endzustände / Ausgänge (Activity Final Nodes):</li>\n<li><code>no input</code>: Fehlerpfad bei verletzter Nullzeiger-Bedingung (korrespondiert zum Rückgabewert <code>E2E_E_INPUTERR_NULL</code> im Gesamtüberblick)</li>\n<li><code>wrong input</code>: Fehlerpfad bei nicht übereinstimmender Datenlänge (korrespondiert zum Rückgabewert <code>E2E_E_INPUTERR_WRONG</code>)</li>\n<li><code>input ok</code>: Erfolgreicher Abschluss der Eingangsprüfung zur Fortsetzung des Schutzablaufs</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Initialknoten erfolgt zwingend zuerst die Prüfung auf Nicht-Null-Zeiger: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>.</li>\n<li>Ergibt diese Bedingung <code>[FALSE]</code>, zweigt der Kontrollfluss direkt zum Endzustand <code>no input</code> ab.</li>\n<li>Ergibt die Nullzeigerprüfung <code>[TRUE]</code>, wird die Datenlänge gegen die konfigurierte Bitzahl evaluiert: <code>Length == Config-&gt;DataLength/8</code>.</li>\n<li>Ist der Längenvergleich <code>[FALSE]</code>, terminiert die Aktivität im Endzustand <code>wrong input</code>.</li>\n<li>Ist der Längenvergleich <code>[TRUE]</code>, erreicht die Ausführung den Zustand <code>input ok</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00404]</code>. Bei der Implementierung ist sicherzustellen, dass die Zeigerprüfungen strikt vor dem lesenden Zugriff auf <code>Config-&gt;DataLength</code> ausgewertet werden, um Nullzeiger-Dereferenzierungen abzufangen. Die Prüfung setzt voraus, dass <code>Config-&gt;DataLength</code> ein Vielfaches von 8 darstellt (Division durch 8 entspricht der Bytelänge). Die Endzustände <code>no input</code>, <code>wrong input</code> und <code>input ok</code> steuern unmittelbar die Fehlerbehandlung bzw. die Rückgabewerte der umschließenden Schutzfunktion <code>E2E_P05Protect()</code>.</p>"}, {"id": "FIG-f634929b48fadaa2", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der AUTOSAR-E2E-Bibliothek (Profile 5). Das Diagramm modelliert den internen Kontrollfluss des Teilschritts „Verify inputs of the protect function“ innerhalb der Funktion <code>E2E_P05Protect()</code>, welche den Eingabeparameter-Check vor der eigentlichen Berechnung von Counter und CRC kapselt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontextfunktion: <code>E2E_P05Protect()</code></li>\n<li>Eingangsparameter / Entitäten:</li>\n<li><code>Config</code>: Zeiger auf die E2E-Profile-5-Konfigurationsstruktur (<code>E2E_P05ConfigType</code>), enthält u. a. das Feld <code>DataLength</code> (Länge in Bits)</li>\n<li><code>State</code>: Zeiger auf den Zustandsvektor (<code>E2E_P05ProtectStateType</code>)</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array (<code>uint8*</code>)</li>\n<li><code>Length</code>: Datenlänge in Bytes (<code>uint16</code>)</li>\n<li>Entscheidungsknoten (Decision Nodes):</li>\n<li>Nullzeiger-Prüfung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code></li>\n<li>Längenprüfung: <code>Length == Config-&gt;DataLength/8</code></li>\n<li>Endzustände / Ausgänge (Activity Final Nodes):</li>\n<li><code>no input</code>: Fehlerpfad bei verletzter Nullzeiger-Bedingung (korrespondiert zum Rückgabewert <code>E2E_E_INPUTERR_NULL</code> im Gesamtüberblick)</li>\n<li><code>wrong input</code>: Fehlerpfad bei nicht übereinstimmender Datenlänge (korrespondiert zum Rückgabewert <code>E2E_E_INPUTERR_WRONG</code>)</li>\n<li><code>input ok</code>: Erfolgreicher Abschluss der Eingangsprüfung zur Fortsetzung des Schutzablaufs</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Initialknoten erfolgt zwingend zuerst die Prüfung auf Nicht-Null-Zeiger: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>.</li>\n<li>Ergibt diese Bedingung <code>[FALSE]</code>, zweigt der Kontrollfluss direkt zum Endzustand <code>no input</code> ab.</li>\n<li>Ergibt die Nullzeigerprüfung <code>[TRUE]</code>, wird die Datenlänge gegen die konfigurierte Bitzahl evaluiert: <code>Length == Config-&gt;DataLength/8</code>.</li>\n<li>Ist der Längenvergleich <code>[FALSE]</code>, terminiert die Aktivität im Endzustand <code>wrong input</code>.</li>\n<li>Ist der Längenvergleich <code>[TRUE]</code>, erreicht die Ausführung den Zustand <code>input ok</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00404]</code>. Bei der Implementierung ist sicherzustellen, dass die Zeigerprüfungen strikt vor dem lesenden Zugriff auf <code>Config-&gt;DataLength</code> ausgewertet werden, um Nullzeiger-Dereferenzierungen abzufangen. Die Prüfung setzt voraus, dass <code>Config-&gt;DataLength</code> ein Vielfaches von 8 darstellt (Division durch 8 entspricht der Bytelänge). Die Endzustände <code>no input</code>, <code>wrong input</code> und <code>input ok</code> steuern unmittelbar die Fehlerbehandlung bzw. die Rückgabewerte der umschließenden Schutzfunktion <code>E2E_P05Protect()</code>.</p>"}], "trans": [{"from": "FIG-12c9ae3be71f6ecb", "to": "FIG-f634929b48fadaa2", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
